/**
 * Regression tests for the font files app/globals.css serves.
 *
 * The three brush fonts used to be served as full TTFs (4.9 / 6.3 / 4.1 MB):
 * a visitor who picked a brush style downloaded a multi-megabyte file for a
 * handful of characters on screen. They are now WOFF2 subsets generated by
 * `npm run fonts:subset-brush`, and the source TTFs live in assets/fonts/
 * where the browser cannot reach them.
 *
 * These tests pin the @font-face rules to the subset files, so a careless
 * edit cannot put a full TTF back into the critical path.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync, existsSync, statSync } from 'node:fs';
import { resolve } from 'node:path';

const ROOT = resolve(__dirname, '..', '..', '..');
const CSS_PATH = resolve(ROOT, 'app', 'globals.css');
const css = readFileSync(CSS_PATH, 'utf8');

/** The brush fonts must not grow back into multi-megabyte files. */
const MAX_BRUSH_FONT_BYTES = 3 * 1024 * 1024;

const BRUSH_FONTS: { family: string; file: string }[] = [
  { family: 'LiuJianMaoCao', file: 'liu-jian-mao-cao.woff2' },
  { family: 'ZCOOLXiaoWei', file: 'zcool-xiaowei.woff2' },
  { family: 'ZhiMangXing', file: 'zhi-mang-xing.woff2' },
];

/** Every font file the stylesheet points at. */
const referencedFiles = [...css.matchAll(/url\('\/fonts\/([^']+)'\)/g)].map((m) => m[1]);

/** The body of every @font-face rule in the stylesheet. */
const fontFaceBlocks = [...css.matchAll(/@font-face\s*\{([^}]*)\}/g)].map((m) => m[1]);

/** The @font-face block that declares the given family. */
function fontFaceBlock(family: string): string {
  const block = fontFaceBlocks.find((body) => body.includes(`font-family: '${family}'`));
  expect(block, `no @font-face rule for ${family}`).toBeDefined();
  return block ?? '';
}

describe('app/globals.css — brush fonts', () => {
  it('serves the brush fonts as WOFF2 subsets', () => {
    for (const { family, file } of BRUSH_FONTS) {
      const block = fontFaceBlock(family);
      expect(block).toContain(`url('/fonts/${file}')`);
      expect(block).toContain("format('woff2')");
    }
  });

  it('does not serve any TrueType file to the browser', () => {
    const ttfRefs = referencedFiles.filter((file) => file.endsWith('.ttf'));
    expect(ttfRefs).toEqual([]);
  });

  it('keeps every referenced font file on disk', () => {
    const missing = referencedFiles.filter(
      (file) => !existsSync(resolve(ROOT, 'public', 'fonts', file)),
    );
    expect(missing).toEqual([]);
  });

  it('keeps the brush font files small', () => {
    for (const { file } of BRUSH_FONTS) {
      const path = resolve(ROOT, 'public', 'fonts', file);
      expect(existsSync(path)).toBe(true);
      expect(statSync(path).size).toBeLessThanOrEqual(MAX_BRUSH_FONT_BYTES);
    }
  });

  it('keeps the TrueType sources out of the served directory', () => {
    const publicFonts = resolve(ROOT, 'public', 'fonts');
    for (const file of ['liu-jian-mao-cao.ttf', 'zcool-xiaowei.ttf', 'zhi-mang-xing.ttf']) {
      expect(existsSync(resolve(publicFonts, file))).toBe(false);
    }
  });
});
